func TestValidationReportPrinter_printFields(t *testing.T) {
	printer := &ValidationReportPrinter{}
	checks := []schema.ValidationCheck{
		{Description: "error", Assertion: false, Severity: schema.ValidationSeverityError},
		{Description: "success", Assertion: true},
		{Description: "warning", Assertion: false, Severity: schema.ValidationSeverityWarning},
	}
	checks = printer.sortChecks(checks)
	assert.Equal(t, "success", checks[0].Description, "first check should be success")
	assert.Equal(t, "warning", checks[1].Description, "second check should be warning")
	assert.Equal(t, "error", checks[2].Description, "third check should be error")
}

package plugintest

import (
	"fmt"

	"github.com/1Password/shell-plugins/sdk/schema"
	"github.com/fatih/color"
)

func PrintValidationReport(plugin schema.Plugin) {
	reports := plugin.DeepValidate()
	printer := &ValidationReportPrinter{
		Reports: reports,
		Format:  PrintFormat{}.ValidationReportFormat(),
	}
	printer.Print()
}

func PrintReportIfErrors(plugin schema.Plugin) (hasErrors bool) {
	pluginReports := plugin.DeepValidate()
	for _, report := range pluginReports {
		if report.HasErrors() {
			printer := &ValidationReportPrinter{
				Format:  PrintFormat{}.ValidationReportFormat(),
				Reports: pluginReports,
			}
			printer.Print()
			return true
		}
	}

	return false
}

type PrintFormat struct {
	Heading *color.Color
	Warning *color.Color
	Error   *color.Color
	Success *color.Color
}

func (pf PrintFormat) ValidationReportFormat() PrintFormat {
	heading := color.New(color.FgCyan, color.Bold)
	warning := color.New(color.FgYellow)
	err := color.New(color.FgRed)
	success := color.New(color.FgGreen)

	return PrintFormat{
		Heading: heading,
		Warning: warning,
		Error:   err,
		Success: success,
	}
}

type ValidationReportPrinter struct {
	Reports []schema.ValidationReport
	Format  PrintFormat
}

func (p *ValidationReportPrinter) Print() {
	if p.Reports == nil || len(p.Reports) == 0 {
		color.Cyan("No reports to print")
		return
	}

	for _, report := range p.Reports {
		p.PrintReport(report)
	}
}

func (p *ValidationReportPrinter) PrintReport(report schema.ValidationReport) {
	p.printHeading(report.Heading)
	p.printChecks(report.Checks)
}

// sortChecks in the order ["success", "warning", "error"]
func (p *ValidationReportPrinter) sortChecks(checks []schema.ValidationCheck) []schema.ValidationCheck {
	var successChecks []schema.ValidationCheck
	var warningChecks []schema.ValidationCheck
	var errorChecks []schema.ValidationCheck

	for _, c := range checks {
		if c.Assertion {
			successChecks = append(successChecks, c)
			continue
		}

		if c.Severity == schema.ValidationSeverityWarning {
			warningChecks = append(warningChecks, c)
			continue
		}

		errorChecks = append(errorChecks, c)
	}

	result := append(successChecks, warningChecks...)
	result = append(result, errorChecks...)

	return result
}

func (p *ValidationReportPrinter) printChecks(checks []schema.ValidationCheck) {
	for _, c := range p.sortChecks(checks) {
		p.printCheck(c)
	}
	fmt.Println()
}

func (p *ValidationReportPrinter) printHeading(heading string) {
	p.Format.Heading.Printf("# %s\n\n", heading)
}

func (p *ValidationReportPrinter) printCheck(check schema.ValidationCheck) {
	if check.Assertion {
		p.Format.Success.Printf("✔ %s\n", check.Description)
		return
	}

	if check.Severity == schema.ValidationSeverityWarning {
		p.Format.Warning.Printf("⚠ %s\n", check.Description)
		return
	}

	p.Format.Error.Printf("✘ %s\n", check.Description)
}

package schema

import (
	"fmt"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestIsTitleCaseWord(t *testing.T) {
	cases := map[string]struct {
		word     string
		expected bool
	}{
		"when title case string provided": {
			word:     "Title",
			expected: true,
		},
		"when empty string provided": {
			word:     "",
			expected: false,
		},
		"when starts with special character": {
			word:     "_",
			expected: false,
		},
		"when string with more than one str provided": {
			word:     "Access Token",
			expected: false,
		},
	}

	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			isTitleCase := IsTitleCaseWord(tc.word)
			assert.Equal(t, tc.expected, isTitleCase, fmt.Sprintf("should return %t", tc.expected))
		})
	}
}

func TestIsTitleCaseString(t *testing.T) {
	cases := map[string]struct {
		str      string
		expected bool
	}{
		"when one str string provided": {
			str:      "Title",
			expected: true,
		},
		"when string has more than one str": {
			str:      "Title Case String",
			expected: true,
		},
		"when empty string provided": {
			str:      "",
			expected: false,
		},
		"when first word in lowercase": {
			str:      "title Case String",
			expected: false,
		},
		"when middle word in lowercase": {
			str:      "Title case String",
			expected: false,
		},
		"when last word in lowercase": {
			str:      "Title Case string",
			expected: false,
		},
	}

	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			isTitleCase := IsTitleCaseString(tc.str)
			assert.Equal(t, tc.expected, isTitleCase, fmt.Sprintf("should return %t", tc.expected))
		})
	}
}

func TestContainsLowercaseLettersOrDigits(t *testing.T) {
	cases := map[string]struct {
		str      string
		expected bool
	}{
		"when there are only lowercase letters": {
			str:      "aws",
			expected: true,
		},
		"when there are only digits": {
			str:      "911",
			expected: true,
		},
		"when there are lowercase letters and digits": {
			str:      "aws911",
			expected: true,
